using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.SGR.PerfilMenus;using GraphApi.Services.SGR.PerfilMenus;namespace GraphApi.Controllers.SGR.PerfilMenus{    /// <summary>    /// Gestión de PerfilMenus: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("SGR/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre PerfilMenus")]    public class PerfilMenusController : Controller    {        private readonly IPerfilMenusService _objService;        public PerfilMenusController(IPerfilMenusService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los PerfilMenus, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="perfilMenuID">PerfilMenuID</param>        /// <param name="perfilID">PerfilID</param>        /// <param name="perfil">Perfil</param>        /// <param name="menuID">MenuID</param>        /// <param name="tituloMenu">TituloMenu</param>        /// <param name="icono">Icono</param>        /// <param name="ruta">Ruta</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de PerfilMenus</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar PerfilMenus",            Description = "Devuelve PerfilMenus aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadPerfilMenus>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadPerfilMenus>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? perfilMenuID,            [FromQuery] int? perfilID,            [FromQuery] string? perfil,            [FromQuery] int? menuID,            [FromQuery] string? tituloMenu,            [FromQuery] string? icono,            [FromQuery] string? ruta,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetPerfilMenusDynamic(                perfilMenuID,                 perfilID,                 perfil,                 menuID,                 tituloMenu,                 icono,                 ruta,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo PerfilMenu.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del PerfilMenu a crear.</param>        /// <returns>El PerfilMenu recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear PerfilMenus",            Description = "Inserta un nuevo PerfilMenu en la base de datos."        )]        [ProducesResponseType(typeof(clReadPerfilMenus), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadPerfilMenus>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreatePerfilMenus objInput)        {            var vCreated = await _objService.CreatePerfilMenus(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de PerfilMenu.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del PerfilMenu.</param>        /// <returns>El PerfilMenu actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar PerfilMenus",            Description = "Actualiza uno o varios campos de PerfilMenu existente."        )]        [ProducesResponseType(typeof(clReadPerfilMenus), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadPerfilMenus>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdatePerfilMenus objInput)        {            var vUpdated = await _objService.UpdatePerfilMenus(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un PerfilMenu por su ID.        /// </summary>        [HttpDelete("{nPerfilMenusID:int}")]        [SwaggerOperation(            Summary = "Eliminar PerfilMenu",            Description = "Borra un PerfilMenu si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nPerfilMenusID)        {            var success = await _objService.DeletePerfilMenus(nPerfilMenusID);            return success ? NoContent() : NotFound();        }    }}